### Second Question
**Problem:** Given multiple numbers, you have to find the numbers between 1 and n (inclusive) which are divisible by all the given numbers.

**Answer:**
```cpp
vector<int> fun(int n, int x, int y){
    vector<int> vec;
    int gc = __gcd(x, y);
    if(gc == 0) return {};
    int new_x = ((x*y) / gc);
    if(new_x == 0) return {};
    new_x = abs(new_x);
    for(int i = new_x; i <= n; i += new_x){
        vec.push_back(i);
    }
    return vec;
}
```

